<template><AppLayout><main class="interview"><p>STATEFUL MOCK INTERVIEW</p><h1>模拟面试</h1><section v-if="!session"><input v-model="topic" placeholder="主题，例如 Java 后端"><button @click="start">开始 5 题面试</button></section><section v-else><header><b>{{ session.topic }}</b><span>{{ session.status }}</span><button v-if="session.status==='IN_PROGRESS'" @click="pauseInterview(session.id).then(load)">中断</button><button v-if="session.status==='PAUSED'" @click="resumeInterview(session.id).then(load)">恢复</button></header><article v-for="turn in session.turns" :key="turn.turnNumber"><b>Q{{turn.turnNumber}}. {{turn.question}}</b><p v-if="turn.answer">你的回答：{{turn.answer}}</p><p v-if="turn.feedback">评分 {{turn.score}}：{{turn.feedback}}</p><textarea v-if="turn.turnStatus==='ASKED'&&session.status==='IN_PROGRESS'" v-model="answer" placeholder="组织你的回答…"/><button v-if="turn.turnStatus==='ASKED'&&session.status==='IN_PROGRESS'" @click="submit">提交回答</button></article></section></main></AppLayout></template>
<script setup>import{ref}from'vue';import AppLayout from'../components/AppLayout.vue';import{startInterview,answerInterview,pauseInterview,resumeInterview}from'../api/interview';const topic=ref('Java 后端');const answer=ref('');const session=ref(null);const start=async()=>{session.value=(await startInterview(topic.value,5)).data.data};const load=async r=>{session.value=(await r).data.data};const submit=async()=>{session.value=(await answerInterview(session.value.id,answer.value)).data.data;answer.value=''};</script>
<style scoped>.interview{max-width:850px;margin:auto;padding:48px;color:#102a43}.interview>p{color:#d65b25;font-weight:800;letter-spacing:.12em}.interview h1{font:42px Georgia,serif}.interview section{background:#fffdf8;border:1px solid #bdd0dc;padding:24px}.interview input,.interview textarea{box-sizing:border-box;width:100%;padding:12px;margin:8px 0;border:1px solid #9fb3c8}.interview textarea{min-height:120px}.interview button{padding:10px 16px;border:0;background:#07599c;color:white;font-weight:700;cursor:pointer}.interview header{display:flex;gap:12px;align-items:center}.interview header span{margin-right:auto;color:#d65b25}.interview article{margin-top:18px;padding-top:16px;border-top:1px solid #d9e4ec}.interview article p{line-height:1.65;color:#486581}</style>
